                            # Doubled quote -> escaped quote
                            field_chars.append('"')
                            i += 2
                        else:
                            # Closing quote
                            i += 1
                            break
                    else:
                        field_chars.append(text[i])
                        i += 1
                field = ''.join(field_chars)
            else:
