                field_chars = []
                while i < n and text[i] != ',' and text[i] != '\r' and text[i] != '\n':
                    field_chars.append(text[i])
                    i += 1
                field = ''.join(field_chars)

            row.append(field)

            # Check what comes after the field
            if i >= n:
                break
            elif text[i] == ',':
                i += 1  # skip comma, continue to next field
                # If the next character is end of input, we still need to add an empty field
                # Actually, if we're at end after comma, the next field is empty
                # Let's handle: after comma, if i >= n, we add empty field and break
                if i >= n:
                    row.append('')
                    break
            elif text[i] == '\r':
                if i + 1 < n and text[i + 1] == '\n':
                    i += 2  # skip CRLF
                else:
                    i += 1  # skip lone CR
                break
            elif text[i] == '\n':
                i += 1  # skip LF
                break
            else:
                # Should not happen in valid CSV, but break to be safe
                break

        rows.append(row)

        # If we're at end of text, stop
        if i >= n:
            break

    return rows
